CHECK (CASE WHEN "value" IS NOT NULL AND "value" NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND min_scale("value") <= 18 AND abs("value") < power(2::numeric, 256) THEN abs("value" * power(10::numeric, 18)) < power(2::numeric, 256) ELSE FALSE END)
CHECK (CASE WHEN "increment" IS NOT NULL AND "increment" NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND "increment" > 0 AND min_scale("increment") <= 28 AND "increment" < power(2::numeric, 96) AND "carry" IS NOT NULL AND "carry" NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND abs("carry") < power(2::numeric, 256) THEN CASE WHEN "increment" * power(10::numeric, min_scale("increment")) < power(2::numeric, 96) AND min_scale("carry") <= greatest(18, min_scale("increment")) THEN abs("carry" * power(10::numeric, greatest(18, min_scale("increment")))) < power(2::numeric, 256) AND 2 * abs("carry") <= "increment" ELSE FALSE END ELSE FALSE END)
CHECK (CASE WHEN "num" IS NOT NULL AND "num" NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND "den" IS NOT NULL AND "den" NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND min_scale("num") = 0 AND min_scale("den") = 0 AND "den" > 0 AND abs("num") < power(2::numeric, 4096) AND "den" < power(2::numeric, 4096) THEN gcd("num", "den") = 1 AND ("num" <> 0 OR "den" = 1) ELSE FALSE END)
